// Retexia — Post. EDIT only the values marked EDIT. API keys live in n8n credentials.
const CONFIG = {
  retexiaKey: 'EDIT: the same value as N8N_POST_KEY in the Retexia panels (Vercel)',
  supabaseUrl: 'https://axommwxevnfpljroejmc.supabase.co', // the Retexia Supabase project
  openaiBase: 'https://api.openai.com/v1',
  textModel: 'gpt-6-luna',
  imageModel: 'gpt-image-2.5-flare', // new design from text
  imageEditModel: 'gpt-image-2.5-sunburst', // design that includes the brand logo
  imageQuality: 'medium', // 'high' = sharper text on the design (better for Sinhala/Tamil letters), costs more
  feedSize: '1088x1360', // 4:5 feed post
  storySize: '1088x1920', // 9:16 story
  useLogo: true, // put brand.logo_path on the design when the business has one
  useProductPhotos: true, // product posts: design with the owner's own product photos (Products → photos), so the real product is shown
  exactProduct: true, // product posts: the real product photo is cut out and pasted onto the design (post.retexia.com /api/post/compose), so it is exactly the photo
  inputFidelity: 'high', // keeps the product's label and shape exact; set '' if the image model rejects input_fidelity
  costs: { text: 0.002, image: 0.04, imageEdit: 0.05 }, // USD, only for usage_monthly
  graphVersion: 'v26.0', // Facebook Graph API version (publishing)
  // Meta app (developers.facebook.com → your app → App settings → Basic), for "Connect Facebook & Instagram".
  metaAppId: 'EDIT: Meta App ID',
  metaAppSecret: 'EDIT: Meta App secret',
  panelUrl: 'https://post.retexia.com', // links in WhatsApp messages
  // Retexia's own WhatsApp line on your Evolution server (owners' messages). Until set, none are sent.
  evolutionUrl: 'EDIT: https://your-evolution-server',
  evolutionKey: 'EDIT: the Evolution API key',
  evolutionInstance: 'EDIT: the instance name, e.g. retexia-post',
};

// Only Retexia may call this webhook (header X-Retexia-Key).
const input = $input.first().json;
const headers = input.headers || {};
if (!CONFIG.retexiaKey || CONFIG.retexiaKey.startsWith('EDIT') || String(headers['x-retexia-key'] || '') !== CONFIG.retexiaKey) {
  throw new Error('Unauthorized: missing or wrong X-Retexia-Key (set retexiaKey in Config).');
}
const body = input.body || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const uuidOr = (v) => (UUID.test(String(v || '').toLowerCase()) ? String(v).toLowerCase() : '');
const businessId = uuidOr(body.business_id);
if (!businessId) throw new Error('business_id is missing or not a UUID.');
const ACTIONS = ['plan', 'design', 'publish', 'delete', 'edit_text', 'whatsapp', 'meta_connect'];
const action = ACTIONS.includes(body.action) ? body.action : 'design';
const CAPTION = ['si', 'si_en', 'singlish', 'en', 'ta'];
const DESIGN = ['si', 'en', 'ta'];
const captionLanguage = CAPTION.includes(body.caption_language) ? body.caption_language : 'en';
const designLanguage = DESIGN.includes(body.design_language) ? body.design_language : 'en';

// Jobs from post.retexia.com (it decides what and when; this workflow does the work).
if (['publish', 'delete', 'edit_text'].includes(action)) {
  const postId = uuidOr(body.post_id);
  if (!postId) throw new Error(action + ' needs post_id.');
  return [{ json: { ...CONFIG, action, businessId, postId, message: String(body.message || '').slice(0, 5000) } }];
}
// "Connect Facebook & Instagram": post.retexia.com checked the signed-in owner and the
// one-time state; here the code is exchanged and the Pages are saved for that business.
if (action === 'meta_connect') {
  if (String(CONFIG.metaAppId).startsWith('EDIT') || String(CONFIG.metaAppSecret).startsWith('EDIT')) throw new Error('Meta app is not set up: fill in metaAppId and metaAppSecret in Config.');
  const code = String(body.code || '');
  const redirectUri = String(body.redirect_uri || '');
  if (!code || !/^https:\/\//.test(redirectUri)) throw new Error('meta_connect needs code and redirect_uri.');
  const graphVersion = /^v\d+\.\d+$/.test(String(body.graph_version || '')) ? body.graph_version : 'v25.0';
  // token_only (admin.retexia.com → Add Facebook & Instagram): answer with the long-lived user token and save
  // nothing; the admin lists the Pages and saves only the one the staff member picks for that customer.
  const tokenOnly = body.token_only === true;
  return [{ json: { ...CONFIG, action, businessId, code, redirectUri, tokenOnly, metaGraph: `https://graph.facebook.com/${graphVersion}` } }];
}

if (action === 'whatsapp') {
  const notReady = ['evolutionUrl', 'evolutionKey', 'evolutionInstance'].filter((k) => !CONFIG[k] || String(CONFIG[k]).startsWith('EDIT'));
  if (notReady.length) return [{ json: { ...CONFIG, action, businessId, notReady: `Retexia's WhatsApp line is not set up in n8n: fill in ${notReady.join(', ')} in the Config node.` } }];
  // Digits with the country code: 00… → …, 07… → 947…, 9 digits → 94… (Sri Lanka).
  let number = String(body.number || '').replace(/[^0-9]/g, '');
  if (number.startsWith('00')) number = number.slice(2);
  if (number.startsWith('0')) number = '94' + number.slice(1);
  else if (number.length === 9) number = '94' + number;
  if (number.length < 8) throw new Error('WhatsApp number missing.');
  const imageUrl = /^https:\/\//.test(String(body.image_url || '')) ? String(body.image_url) : '';
  return [{ json: { ...CONFIG, action, businessId, number, text: String(body.text || '').slice(0, 4000), image_url: imageUrl } }];
}

if (action === 'plan') {
  const slots = (Array.isArray(body.slots) ? body.slots : []).slice(0, 10).map((s) => ({
    key: String(s.key || ''), format: s.format === 'story' ? 'story' : 'post', time: String(s.time || ''), hint: s.hint ? String(s.hint).slice(0, 400) : '',
  })).filter((s) => s.key);
  if (!slots.length) throw new Error('No slots to plan.');
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(body.date || '')) ? body.date : new Date().toISOString().slice(0, 10);
  const promptLanguage = ['si', 'en', 'ta'].includes(body.prompt_language) ? body.prompt_language : 'en';
  return [{ json: { ...CONFIG, action, businessId, date, slots, captionLanguage, designLanguage, promptLanguage } }];
}

// What the post is about: one product, a group of products, or the whole business.
const f = body.focus && typeof body.focus === 'object' ? body.focus : {};
const focus = ['product', 'group'].includes(f.type) && uuidOr(f.id) ? { type: f.type, id: uuidOr(f.id) } : { type: 'business' };

const prompt = String(body.prompt || '').trim();
if (prompt.length < 3) throw new Error('Send a prompt describing the post.');
return [{ json: {
  ...CONFIG, action, businessId,
  postId: uuidOr(body.post_id),
  focus,
  prompt: prompt.slice(0, 1600),
  format: body.format === 'story' ? 'story' : 'post',
  captionLanguage, designLanguage,
  publish: body.publish === true,
  scheduledAt: typeof body.scheduled_at === 'string' ? body.scheduled_at : '',
} }];

// One text call writes the whole day's playlist: one idea (prompt) per slot.
const cfg = $('Config').first().json;
const ctx = $input.first().json.ctx;
if (!ctx || !ctx.business) throw new Error('Business not found: ' + cfg.businessId);
const b = ctx.business;
const brand = b.brand || {};
const LANG = { si: 'Sinhala (Sinhala script)', en: 'English', ta: 'Tamil (Tamil script)' };
const money = (p) => (p.price == null ? 'no price' : `${p.currency || ''} ${Number(p.price).toLocaleString('en-US')}`.trim());
const facts = [
  `Business: ${b.name}${b.category ? ` (${b.category})` : ''}${b.country ? `, ${b.country}` : ''}`,
  b.brand_brief && `About: ${b.brand_brief}`,
  (ctx.products || []).length && `Products: ${ctx.products.map((p) => `${p.name} = ${money(p)}${p.description ? ` (${p.description})` : ''}`).join('; ')}`,
  (ctx.offers || []).length && `Active offers: ${ctx.offers.map((o) => `${o.title}${o.discount ? `, ${o.discount}` : ''}${o.price ? `, ${o.price}` : ''}, ends ${o.ends}${o.details ? ` (${o.details})` : ''}`).join('; ')}`,
  brand.contact && `Contact: ${JSON.stringify(brand.contact)}`,
].filter(Boolean);

const instructions = [
  'You plan one day of Facebook and Instagram content for a small business in Sri Lanka.',
  'For every SLOT write one idea that a designer AI will turn into a finished picture (and, for posts, a caption).',
  'Use ONLY the FACTS and the slot HINT. Never invent prices, discounts, dates, phone numbers or claims.',
  'If a slot has a HINT (an offer, the owner\'s note, or a Focus), that slot must be about it. "Focus: only the product X" = an idea about X only; "Focus: the business as a whole" = an idea about the business (what it is, what it offers, why people choose it), not one product.',
  'Vary the angles across the day: product showcase, useful tip, behind the scenes, customer favourite, offer, question to the audience, seasonal or local moment. Spread the products; do not repeat an idea from RECENT.',
  'post slots: a feed post (4:5 picture + caption). story slots: a quick full-screen story with one short message (today-only reminder, close-up, question, countdown).',
  `title: max 6 words. prompt: 1-3 concrete sentences: what to show, which product (and its price only if in FACTS), the message and the feeling. Write title and prompt in ${LANG[cfg.promptLanguage] || 'English'}.`,
  'angle: one or two words in English (e.g. showcase, tip, offer). product: the product name from FACTS, or "".',
  'Return exactly one item per SLOT, with the same key.',
].join('\n');

const slots = cfg.slots.map((s) => `- key=${s.key} | ${s.format} at ${s.time}${s.hint ? ` | HINT: ${s.hint}` : ''}`);
const recent = (ctx.recent_prompts || []).map((p) => '- ' + String(p).replace(/\s+/g, ' '));
const userText = [`DATE: ${cfg.date}`, '', 'FACTS:', ...facts.map((f) => '- ' + f), '', 'SLOTS:', ...slots, recent.length ? '\nRECENT (do not repeat):\n' + recent.join('\n') : ''].join('\n');

const str = { type: 'string' };
const schema = {
  type: 'object', additionalProperties: false, required: ['items'],
  properties: { items: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['key', 'title', 'prompt', 'angle', 'product'],
    properties: { key: str, title: str, prompt: str, angle: str, product: str } } } },
};
return [{ json: { body: {
  model: cfg.textModel, instructions,
  input: [{ role: 'user', content: [{ type: 'input_text', text: userText }] }],
  text: { format: { type: 'json_schema', name: 'day_playlist', strict: true, schema } },
  max_output_tokens: 6000,
} } }];

const res = $input.first().json;
let text = res.output_text;
if (!text) for (const o of res.output || []) for (const c of o.content || []) { if (c.type === 'output_text') text = c.text; if (c.type === 'refusal') throw new Error('OpenAI refused: ' + c.refusal); }
let out;
try { out = JSON.parse(text); } catch (e) { throw new Error('Bad JSON from OpenAI: ' + String(text).slice(0, 300)); }
const keys = new Set($('Config').first().json.slots.map((s) => s.key));
const items = (out.items || []).filter((i) => keys.has(i.key) && String(i.prompt || '').trim().length > 3)
  .map((i) => ({ key: i.key, title: String(i.title || '').slice(0, 120), prompt: String(i.prompt).trim().slice(0, 1500), angle: String(i.angle || '').slice(0, 60), product: String(i.product || '').slice(0, 120) }));
return [{ json: { items } }];

// One text call writes the captions AND the design brief (with the exact text for the picture).
const cfg = $('Config').first().json;
const ctx = $input.first().json.ctx;
if (!ctx || !ctx.business) throw new Error('Business not found: ' + cfg.businessId);
const b = ctx.business;
const brand = b.brand || {};
const story = cfg.format === 'story';
const money = (p) => (p.price == null ? 'no price' : `${p.currency || ''} ${Number(p.price).toLocaleString('en-US')}`.trim());
const facts = [
  `Business: ${b.name}${b.category ? ` (${b.category})` : ''}${b.country ? `, ${b.country}` : ''}`,
  b.brand_brief && `About: ${b.brand_brief}`,
  brand.tone && `Tone: ${typeof brand.tone === 'string' ? brand.tone : JSON.stringify(brand.tone)}`,
  brand.emoji === false ? 'Emoji: none' : 'Emoji: a few are fine',
  (brand.always_words || []).length && `Words the brand likes: ${brand.always_words.join(', ')}`,
  (brand.never_words || []).length && `NEVER use: ${brand.never_words.join(', ')}`,
  brand.contact && `Contact: ${JSON.stringify(brand.contact)}`,
  (ctx.products || []).length && `Products: ${ctx.products.map((p) => `${p.name} = ${money(p)}${p.description ? ` (${p.description})` : ''}`).join('; ')}`,
].filter(Boolean);

const CAPTION = {
  si: 'Sinhala, in Sinhala script (Unicode). Natural, everyday Sri Lankan Sinhala as people really speak: warm, simple, short sentences; not formal or literary. Keep product names, prices and phone numbers exactly as in FACTS.',
  si_en: 'Sinhala in Sinhala script (natural everyday Sri Lankan Sinhala), then one short English line with the same call to action.',
  singlish: 'Singlish: Sinhala words written in English letters, the way Sri Lankans text each other (e.g. "Ada vitharai!", "Order karanna message ekak danna"). No Sinhala script.',
  en: 'Simple, friendly English for Sri Lankan customers.',
  ta: 'Tamil, in Tamil script: natural Sri Lankan Tamil, warm and simple.',
};
const DESIGN = {
  si: 'Sinhala, in Sinhala script (Unicode Sinhala letters). Very short, common, correctly spelled words. Keep prices, phone numbers and brand names as written.',
  en: 'English. Very short, clear words.',
  ta: 'Tamil, in Tamil script. Very short, common, correctly spelled words. Keep prices, phone numbers and brand names as written.',
};

const focus = ctx.focus || { type: 'business' };
const productNames = (ctx.products || []).map((p) => p.name).join(', ');
const FOCUS = {
  product: `This ${story ? 'story' : 'post'} is about ONE product only: ${focus.name || productNames}. Feature only it; do not mention other products.`,
  group: `This ${story ? 'story' : 'post'} is about the group "${focus.name || ''}": ${productNames}. Show them together as one range; do not feature products outside the group.`,
  business: `This ${story ? 'story' : 'post'} is about the business as a whole (use "About" in the FACTS): what it is, what it offers and why people choose it. Do not make it about one product or its price.`,
  all: '',
};

const instructions = [
  'You are a senior social media designer and copywriter for small businesses in Sri Lanka.',
  story
    ? 'Turn the REQUEST into one 9:16 STORY: a full-screen designed graphic with a few words. Stories show no caption, so caption_instagram and caption_facebook must be "" and hashtags [].'
    : 'Turn the REQUEST into one 4:5 feed post: a designed graphic (banner style, with text on it) plus captions.',
  FOCUS[focus.type] || '',
  (cfg.useProductPhotos && (ctx.photos || []).length) ? `The designer gets real photo(s) of the ${focus.type === 'group' ? 'products' : 'product'}. In design_prompt, build the scene, props, lighting and layout around THE PRODUCT FROM THE PHOTO as the hero; do not describe or change its packaging, label, shape or colours (they come from the photo). The product stands in the centre of the lower middle of the picture: plan the headline and subline above it, the CTA and footer below it, a price badge beside it.` : '',
  'Use ONLY the FACTS and the REQUEST. Never invent prices, discounts, dates, phone numbers, addresses, links, awards, reviews, or health/income claims. If unsure, leave it out.',
  'The REQUEST is often only a few words: expand it with the concrete details in the FACTS (what the business is, the product, what makes it special, options, sizes, price, area, how to order) so the post feels specific to this business, never generic.',
  story ? '' : `caption_instagram in ${CAPTION[cfg.captionLanguage] || CAPTION.en} A strong hook in the first line, then 3-5 short lines with real details from the FACTS (benefits, what is included, price if given, delivery or area), then one clear call to action (message / call / visit, using Contact). Short lines with line breaks, a few fitting emoji unless the brand says none, no hashtags.`,
  story ? '' : 'caption_facebook: same language and idea, a little longer and more conversational, ending with how to order or contact (copied exactly from Contact), no hashtags.',
  story ? '' : 'hashtags: 3-8, without #, mix local and topic tags (Latin letters are easier to find; Sinhala tags are fine too).',
  `Text on the design, in ${DESIGN[cfg.designLanguage] || DESIGN.en} headline max ${story ? 5 : 6} words (the big message); subline max ${story ? 8 : 12} words or ""; ` +
    'price_text only a price/discount stated in FACTS or REQUEST, else ""; cta max 4 words or ""; ' +
    'footer: one phone/website/handle copied exactly from Contact, else "".',
  'design_prompt: art direction for an image model (in English), 4-6 sentences, like a top agency brief for a premium, scroll-stopping post: ' +
    'the visual style that fits this business and audience (photographic product hero, lifestyle scene, or bold graphic poster); ' +
    'the main subject in detail (the real product or service from FACTS, its look, textures, props, setting), lighting and camera angle, depth and background; ' +
    `a clean layout with clear zones for HEADLINE (biggest), SUBLINE, PRICE badge, CTA button and FOOTER${story ? ' (keep the top 14% and bottom 20% free of text)' : ''}; ` +
    'a colour palette built on the brand colours with strong contrast; modern typography with clear hierarchy; the mood. ' +
    'Refer to the texts only by those labels, do not write them out.',
  'alt_text: one plain English sentence describing the image.',
].filter(Boolean).join('\n');

const recent = (ctx.recent || []).map((c) => '- ' + String(c).replace(/\s+/g, ' '));
const userText = [`REQUEST: ${cfg.prompt}`, '', 'FACTS:', ...facts.map((f) => '- ' + f), recent.length ? '\nRecent posts (do not repeat their openings):\n' + recent.join('\n') : ''].filter((x) => x !== '').join('\n');

const str = { type: 'string' };
const schema = {
  type: 'object', additionalProperties: false,
  required: ['headline', 'subline', 'price_text', 'cta', 'footer', 'design_prompt', 'caption_instagram', 'caption_facebook', 'hashtags', 'alt_text'],
  properties: { headline: str, subline: str, price_text: str, cta: str, footer: str, design_prompt: str, caption_instagram: str, caption_facebook: str, hashtags: { type: 'array', items: str }, alt_text: str },
};
return [{ json: {
  factsText: facts.join('\n') + '\n' + cfg.prompt,
  body: { model: cfg.textModel, instructions, input: [{ role: 'user', content: [{ type: 'input_text', text: userText }] }],
          text: { format: { type: 'json_schema', name: 'post_design', strict: true, schema } }, max_output_tokens: 4000 },
} }];

// Read the copy, drop on-picture text with numbers not found in the facts, build the image prompt.
const cfg = $('Config').first().json;
const ctx = $('Load business').first().json.ctx;
const req = $('Build copy request').first().json;
const res = $('OpenAI: write post').first().json;
// Signed URLs from the batch sign (one item per path); failures are just left out.
const signed = new Map();
for (const it of $('Sign logo and photos').all()) for (const j of [].concat(Array.isArray(it.json) ? it.json : Array.isArray(it.json.data) ? it.json.data : [it.json])) if (j && j.path && j.signedURL) signed.set(j.path, j.signedURL);
const url = (path) => (signed.get(path) ? cfg.supabaseUrl + '/storage/v1' + signed.get(path) : '');
const b = ctx.business;
const brand = b.brand || {};
const story = cfg.format === 'story';

let text = res.output_text;
if (!text) for (const o of res.output || []) for (const c of o.content || []) { if (c.type === 'output_text') text = c.text; if (c.type === 'refusal') throw new Error('OpenAI refused: ' + c.refusal); }
let copy;
try { copy = JSON.parse(text); } catch (e) { throw new Error('Bad JSON from OpenAI: ' + String(text).slice(0, 300)); }

// Accuracy guard: every number on the design must appear in the facts or the request.
const blob = req.factsText.replace(/,/g, '');
const nums = (s) => (String(s).match(/\d[\d.,]*/g) || []).map((n) => n.replace(/[.,]+$/, '').replace(/,/g, ''));
const verified = (s) => nums(s).every((n) => blob.includes(n));
const dropped = [];
for (const k of ['headline', 'subline', 'price_text', 'cta', 'footer']) {
  copy[k] = String(copy[k] || '').trim();
  if (copy[k] && !verified(copy[k])) { dropped.push(`${k}: ${copy[k]}`); copy[k] = ''; }
}
if (!copy.headline) copy.headline = b.name;

const SCRIPT = {
  si: 'All words are SINHALA in Sinhala Unicode script. Render every Sinhala letter, vowel sign (pili) and conjunct exactly as given, in a clean modern Sinhala typeface (like Noto Sans Sinhala or Iskoola Pota). Never replace Sinhala with English letters or invent letters.',
  ta: 'All words are TAMIL in Tamil Unicode script. Render every Tamil letter and vowel sign exactly as given, in a clean modern Tamil typeface (like Noto Sans Tamil). Never replace Tamil with English letters.',
  en: '',
};
const lines = [
  ['HEADLINE (largest, boldest)', copy.headline],
  ['SUBLINE', copy.subline],
  ['PRICE (badge or tag)', copy.price_text],
  ['CTA (button style)', copy.cta],
  ['FOOTER (small)', copy.footer],
].filter(([, v]) => v).map(([k, v]) => `- ${k}: "${v}"`);

// Exact product: the real photo, cut out and placed on a transparent canvas (also the mask).
const prep = $input.first().json || {};
const exact = !!(prep.ok && prep.canvas_url && prep.cutout_path);
const zone = prep.zone || { top: 30, bottom: 78, width: 62 };
const photos = exact ? [] : cfg.useProductPhotos ? (ctx.photos || []).map(url).filter(Boolean).slice(0, 4) : [];
const logoUrl = brand.logo_path ? url(brand.logo_path) : '';
const useLogo = !!(cfg.useLogo && logoUrl);
const group = (ctx.focus || {}).type === 'group';
const n = photos.length;
const EXACT = exact ? [
  'IMAGE 1 is the canvas: the REAL product photo is already in its final place (the only non-transparent part). Design the whole picture around it, filling every transparent area.',
  `The product stays EXACTLY as it is, where it is, at this size (centred, between ${zone.top}% and ${zone.bottom}% of the height): do not redraw, move, resize, recolour, duplicate or cover it, and put no text or objects over it.`,
  'Ground it naturally: a surface or podium under it with a soft contact shadow, background and props that suit it, lighting and colours that match its photo.',
  `Layout: HEADLINE and SUBLINE above the product, CTA and FOOTER below it, the PRICE badge beside it, all clear of the product.`,
].join('\n') : '';
const PRODUCT = n ? [
  `PRODUCT PHOTO${n > 1 ? 'S' : ''}: attached image${n > 1 ? `s 1-${n} are` : ' 1 is a'} real photo${n > 1 ? 's' : ''} of ${group ? 'the products (one each)' : 'the product (different angles)'}.`,
  `Show ${group ? 'these exact products together' : 'THIS exact product'} as the hero: the same packaging, shape, proportions, label text, logo and colours, unchanged and fully recognisable. Do not redraw, restyle, translate or replace the label, and do not invent a different product.`,
  'Cut the product out of its photo background and place it naturally in the new scene, with matching lighting, realistic shadows and reflections. You may change the background, angle of the scene and props, never the product itself.',
].join('\n') : '';
const prompt = [
  `A finished, professional social media ${story ? 'STORY design (9:16 vertical, full screen)' : 'post design (4:5 feed)'} for "${b.name}"${b.category ? `, a ${b.category} business` : ''}${b.country ? ` in ${b.country}` : ''}.`,
  copy.design_prompt,
  EXACT || PRODUCT,
  (brand.colors || []).length ? `Brand colours: ${brand.colors.join(', ')}.` : '',
  brand.font ? `Typography in the style of: ${brand.font}.` : '',
  'TEXT ON THE DESIGN - render exactly as written, perfectly spelled, letter for letter, and no other words:',
  ...lines,
  SCRIPT[cfg.designLanguage] || '',
  story ? 'Keep the top 14% and the bottom 20% of the picture free of text (the app shows its own buttons there).' : '',
  useLogo ? `${n || exact ? 'The last attached image is the brand logo: place it' : 'Place the attached logo'} small in a top corner, exactly as it is.` : n || exact ? 'Do not add any other logo or brand mark (the one on the product label stays).' : 'Do not draw any logo or brand mark.',
  'Quality: a premium, magazine-quality design made by a top design agency. Rich detail and realistic textures, professional lighting with soft shadows, a balanced composition with generous margins, one clear focal point.',
  'Typography: clear hierarchy (headline largest and boldest), high contrast against the background, crisp and fully legible, all text away from the outer edges. No watermarks, no extra text, no clutter.',
].filter(Boolean).join('\n');

const refs = [...(exact ? [prep.canvas_url] : photos), ...(useLogo ? [logoUrl] : [])];
const body = {
  model: refs.length ? cfg.imageEditModel : cfg.imageModel,
  prompt,
  size: story ? cfg.storySize : cfg.feedSize,
  quality: cfg.imageQuality,
  output_format: 'jpeg',
  output_compression: 90,
  n: 1,
};
if (refs.length) body.images = refs.map((image_url) => ({ image_url }));
if ((n || exact) && cfg.inputFidelity) body.input_fidelity = cfg.inputFidelity;
if (exact) body.mask = { image_url: prep.canvas_url };

const tags = story ? [] : (copy.hashtags || []).map((t) => '#' + String(t).replace(/^#+/, '').replace(/[^\p{L}\p{N}\p{M}_]/gu, '')).filter((t) => t.length > 1).slice(0, 8);
const ig = story ? '' : String(copy.caption_instagram || '').trim();
return [{ json: {
  endpoint: refs.length ? 'edits' : 'generations',
  body,
  caption: ig,
  variants: story ? {} : { facebook: { caption: String(copy.caption_facebook || '').trim() }, instagram: { caption: ig + (tags.length ? '\n\n' + tags.join(' ') : ''), hashtags: tags } },
  altText: String(copy.alt_text || '').trim(),
  brief: {
    headline: copy.headline, subline: copy.subline, price_text: copy.price_text, cta: copy.cta, footer: copy.footer,
    design_prompt: copy.design_prompt, alt_text: copy.alt_text, dropped_text: dropped, logo: useLogo, product_photos: n, exact_product: exact, ...(exact ? { product_photo: prep.photo } : {}),
    caption_language: cfg.captionLanguage, design_language: cfg.designLanguage, ...(cfg.postId ? {} : { prompt: cfg.prompt, focus: ctx.focus && ctx.focus.type !== 'all' ? ctx.focus : { type: 'business' } }),
  },
} }];

const res = $input.first().json;
const cfg = $('Config').first().json;
const b64 = res && res.data && res.data[0] && res.data[0].b64_json;
if (!b64) throw new Error('OpenAI returned no image: ' + JSON.stringify(res).slice(0, 300));
const fileName = `${cfg.format}-${Date.now()}.jpg`;
const bytes = Math.floor((b64.length * 3) / 4) - (b64.endsWith('==') ? 2 : b64.endsWith('=') ? 1 : 0);
return [{
  json: { storage_path: `${cfg.businessId}/ai/${fileName}`, bytes },
  binary: { data: { data: b64, mimeType: 'image/jpeg', fileName, fileExtension: 'jpg' } },
}];

// One account of one post: what to call on Facebook / Instagram.
const s = $('Config').first().json;
const job = $('Claim post to publish').item.json;
const signed = $json.signedURL;
const base = String(s.supabaseUrl).replace(/\/$/, '');
const route = !job.token ? 'skip'
  : job.platform === 'facebook' ? (job.is_story ? 'fb_story' : 'fb_post')
  : job.is_story ? 'ig_story' : 'ig_post';
return { json: {
  publication_id: job.publication_id,
  post_id: job.post_id,
  route,
  graph: `https://graph.facebook.com/${s.graphVersion}`,
  node: job.external_id, // Facebook Page id or Instagram account id
  token: job.token || '',
  caption: job.caption || '',
  image_url: signed ? (String(signed).startsWith('http') ? signed : base + '/storage/v1' + signed) : '',
  error: !job.token ? { message: 'Not connected through Retexia yet. Reconnect with Facebook.', code: 190 } : undefined,
} };

// Published on Instagram: its id and link.
return { json: {
  id: $('IG published?').item.json.id,
  permalink: $json.permalink || null,
  container_id: $('Wait for Instagram').item.json.id,
} };

// Turns Meta's answer into a result for post.n8n_publish_result().
let job;
try { job = $('Prepare publish').item.json; } catch (e) { job = { ...$('Claim post to publish').item.json, route: 'sign' }; }
const r = $json || {};

// Same rules as before: retry, ask the owner to reconnect, or a problem with the content.
function classify(e) {
  if (!e || typeof e !== 'object' || typeof e.code !== 'number') {
    const message = typeof e === 'string' ? e : (e && (e.description || e.message)) || 'Meta did not answer';
    return { kind: 'temporary', message: String(message).slice(0, 500) };
  }
  const code = e.code, sub = e.error_subcode;
  const message = String(e.error_user_msg || e.message || 'Meta error ' + code).slice(0, 500);
  if (code === 190 || code === 102 || code === 10 || (code >= 200 && code < 300) || [463, 467, 2207050].includes(sub)) return { kind: 'needs_user', message };
  if (e.is_transient || [1, 2, 4, 17, 32, 341, 368, 613].includes(code) || sub === 2207027 || code === 9007) return { kind: 'temporary', message };
  return { kind: 'content', message };
}

const id = r.post_id || r.id;
if (!r.error && id && job.route !== 'sign') {
  return { json: {
    publication_id: job.publication_id, ok: true, external_id: String(id),
    permalink: r.permalink || (job.route === 'fb_post' ? `https://www.facebook.com/${id}` : null),
    container_id: r.container_id || null,
  } };
}
const c = classify(r.error || (job.route === 'sign' ? 'Could not read the picture file' : 'Meta did not return an id'));
return { json: { publication_id: job.publication_id, ok: false, error_kind: c.kind, error: c.message } };

// Meta's answer for one account.
const job = $('Load delete jobs').item.json;
const r = $json || {};
const e = r.error;
const gone = e && e.code === 100 && e.error_subcode === 33; // already deleted on Facebook / Instagram
const ok = !e ? (r.success === true || r.success === undefined) : gone;
const error = ok ? null : String((e && (e.error_user_msg || e.message || e.description)) || (typeof e === 'string' ? e : 'Meta did not accept it')).slice(0, 300);
return { json: { publication_id: job.publication_id, platform: job.platform || 'facebook', ok, error } };

// One answer for post.retexia.com.
